  const [searchTerm, setSearchTerm] = useState("")
  const [isInstalling, setIsInstalling] = useState(false)
  const supabase = useClerkSupabaseClient()

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
