}

export function CodeEditorDialog({
  isOpen,
  setIsOpen,
  code,
  demoCode,
  componentSlug,
  registryToPublish,
  directRegistryDependencies,
  demoDirectRegistryDependencies = [],
  customTailwindConfig,
  customGlobalCss,
  onSave,
  mode,
  currentState,
}: CodeEditorDialogProps) {
  const { resolvedTheme } = useTheme()
  const isDarkTheme = resolvedTheme === "dark"
  const [editedCode, setEditedCode] = useState(
    mode === "component"
      ? code
      : mode === "demo"
        ? demoCode
        : mode === "styles" && customTailwindConfig
          ? customTailwindConfig
          : "",
  )
  const [isSaving, setIsSaving] = useState(false)
  const [activeStyleTab, setActiveStyleTab] = useState<"tailwind" | "globals">(
    "tailwind",
  )

  const methods = useForm({
    defaultValues: {
      code: currentState.code,
      name: "",
      component_slug: componentSlug,
      registry: registryToPublish,
      demos: [
        {
          name: "",
          demo_code: currentState.demoCode,
          demo_slug: "",
          tags: [],
          preview_image_data_url: "",
          preview_video_data_url: "",
          demo_direct_registry_dependencies:
            currentState.demoDirectRegistryDependencies,
          demo_dependencies: {},
        },
      ],
      direct_registry_dependencies: currentState.directRegistryDependencies,
      tailwind_config: currentState.tailwindConfig,
      globals_css: currentState.globalsCss,
    },
  })

  const [previewKey, setPreviewKey] = useState<string>(
    () =>
      `${code}-${demoCode}-${customTailwindConfig}-${customGlobalCss}-${isDarkTheme}`,
  )

  const [currentStateValue, setCurrentStateValue] = useState(currentState)

  const handleCodeChange = (value: string) => {
    setEditedCode(value)
    if (mode === "component") {
      methods.setValue("code", value)
      setCurrentStateValue({
        ...currentStateValue,
        code: value,
      })
    } else if (mode === "demo") {
      methods.setValue("demos.0.demo_code", value)
      setCurrentStateValue({
        ...currentStateValue,
        demoCode: value,
      })
    }
    setPreviewKey(`${value}-${Date.now()}`)
  }

  const handleSave = async () => {
    try {
      setIsSaving(true)
      await onSave(editedCode)
      setIsOpen(false)
    } catch (error) {
      console.error("Error saving code:", error)
    } finally {
      setIsSaving(false)
    }
  }

  const previewProps = {
    code: mode === "component" ? editedCode : currentStateValue.code,
    demoCode: mode === "demo" ? editedCode : currentStateValue.demoCode,
    directRegistryDependencies:
      currentStateValue.directRegistryDependencies ?? [],
    demoDirectRegistryDependencies:
      currentStateValue.demoDirectRegistryDependencies ?? [],
    customTailwindConfig:
      mode === "styles" && activeStyleTab === "tailwind"
        ? editedCode
        : currentStateValue.tailwindConfig,
    customGlobalCss:
      mode === "styles" && activeStyleTab === "globals"
        ? editedCode
        : currentStateValue.globalsCss,
  }

  return (
    <FormProvider {...methods}>
      <Sheet open={isOpen} onOpenChange={setIsOpen}>
        <SheetContent
          side="center"
          className="w-screen h-screen p-0 sm:max-w-none [&_button[aria-label='Close']]:hidden"
          hideCloseButton
        >
          <div className="flex flex-col h-screen">
            <div className="flex items-center justify-between px-4 py-1 border-b">
              <div className="flex items-center gap-4">
                <div className="font-medium text-sm">
                  {mode === "component" && "Edit Component Code"}

"use client"

import * as shiki from "shiki"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { toast } from "sonner"
import { useState, useEffect, useCallback } from "react"
import { useTheme } from "next-themes"

// Create a highlighter instance that can be reused
let highlighterPromise: Promise<shiki.Highlighter> | null = null

const getHighlighter = async () => {
  if (!highlighterPromise) {
    highlighterPromise = shiki.createHighlighter({
      themes: ["github-dark", "github-light"],
      langs: [
        "json",
        "typescript",
        "javascript",
        "tsx",
        "jsx",
        "html",
        "css",
        "bash",
        "markdown",
        "plaintext",
      ],
    })
  }
  return highlighterPromise
}

// Add custom styles for shiki container
const customShikiStyles = `
.code-wrapper .shiki,
.code-wrapper .shiki pre {
  background-color: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: inherit !important;
}
.code-wrapper .shiki code {
  display: inline-block;
  min-width: 100%;
}
`

const codeVariants = cva(
  "font-mono rounded-md cursor-pointer overflow-auto transition-all duration-200 relative shadow-inner",
  {
    variants: {
      display: {
        inline: "inline-flex bg-secondary py-0 px-1",
        block: "block bg-secondary p-2 mt-2 mb-4",
      },
      fontSize: {
        xs: "text-xs",
        sm: "text-sm",
        md: "text-md",
        lg: "text-lg",
      },
    },
    defaultVariants: {
      display: "inline",
      fontSize: "xs",
    },
  },
)

interface CodeProps
  extends Omit<
      React.HTMLAttributes<HTMLDivElement>,
      keyof VariantProps<typeof codeVariants>
    >,
    VariantProps<typeof codeVariants> {
  code: string
  fontSize?: "xs" | "sm" | "md" | "lg"
  language?: string
  background?: string
}

const Code = ({
  code,
  language = "tsx",
  display,
  fontSize,
  className,
  background,
  style,
  ...props
}: CodeProps) => {
  const [isCopied, setIsCopied] = useState(false)
  const [highlightedCode, setHighlightedCode] = useState("")
  const { resolvedTheme } = useTheme()

  const highlight = useCallback(async () => {
    try {
      const highlighter = await getHighlighter()
      const supportedLanguages = await highlighter.getLoadedLanguages()
      const langToUse = supportedLanguages.includes(
        language as shiki.BundledLanguage,
      )
        ? language
        : "plaintext"

      const html = await highlighter.codeToHtml(code, {
        lang: langToUse as shiki.BundledLanguage,
        theme: resolvedTheme === "dark" ? "github-dark" : "github-light",
      })
      setHighlightedCode(html)
    } catch (error) {
      console.error("Failed to highlight code:", error)
      setHighlightedCode(`<pre><code>${code}</code></pre>`)
    }
  }, [code, language, resolvedTheme])

  useEffect(() => {
    highlight()
  }, [highlight])

  const handleCopyClick = async () => {
    if (isCopied) return
    await navigator.clipboard.writeText(code)
    setIsCopied(true)
    toast.success("Copied to clipboard", {
      duration: 1500,
      className: "select-none",
    })

    setTimeout(() => {
      setIsCopied(false)
    }, 1000)
  }

  return (
    <>
      <style>{customShikiStyles}</style>
      <div
        onClick={handleCopyClick}
        role="button"
        tabIndex={0}
        aria-label="Click to copy code"
        className={cn(
          "code-wrapper",
          codeVariants({ fontSize, display }),
          className,
          "focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:outline-none",
          "relative",
          isCopied &&
            "before:absolute before:inset-0 before:rounded-md before:pointer-events-none before:bg-emerald-400/5 before:border before:border-emerald-400/20 before:animate-copy-success",
        )}
        style={{
          backgroundColor: background,
          ...style,
        }}
        {...props}
      >
        <div
          className="shiki-wrapper"
          dangerouslySetInnerHTML={{ __html: highlightedCode }}
        />
      </div>
    </>
  )
}

Code.displayName = "Code"

export { Code }

