  <TTag extends ElementType = typeof DEFAULT_INPUT_TAG>(
    props: InputProps<TTag> & RefProp<typeof InputFn>
  ): React.JSX.Element
}

export let Input = forwardRefWithAs(InputFn) as _internal_ComponentInput

